create table public.assets (id uuid primary key default gen_random_uuid(), owner_id uuid not null references public.profiles(id) on delete cascade, bucket text not null, storage_path text not null, file_name text not null, mime_type text not null, file_size bigint not null check (file_size >= 0), asset_type text not null, metadata jsonb, created_at timestamptz not null default now(), unique (bucket, storage_path));;
